/// One implementation of every method, shared by the binary and the
/// JSON-RPC endpoints.
pub trait Service: Sync {
    /// Protocol and build identity.
    fn daemon_version(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<VersionInfo, RpcError>> + Send;
    /// Process, socket, log, and tmux endpoint state.
    fn daemon_status(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<DaemonStatus, RpcError>> + Send;
    /// Stop the daemon; tmux sessions and panes keep running.
    fn daemon_shutdown(
        &self,
        params: Empty,
    ) -> impl ::core::future::Future<Output = Result<ShutdownResult, RpcError>> + Send;
    /// Sessions, windows, and panes of one endpoint.
    fn tmux_topology(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<Topology, RpcError>> + Send;
    /// Run a typed action and report its observed outcome.
    fn actions_submit(
        &self,
        params: SubmitAction,
    ) -> impl ::core::future::Future<Output = Result<ActionRecord, RpcError>> + Send;
    fn actions_get(
        &self,
        params: ActionQuery,
    ) -> impl ::core::future::Future<Output = Result<ActionRecord, RpcError>> + Send;
    fn actions_list(
        &self,
        params: ActionListParams,
    ) -> impl ::core::future::Future<Output = Result<ActionList, RpcError>> + Send;
    /// Bounded text, cursor, and size from a pane's canonical mirror.
    fn terminal_read(
        &self,
        params: ReadParams,
    ) -> impl ::core::future::Future<Output = Result<TerminalText, RpcError>> + Send;
    /// Every mirrored pane and its state.
    fn terminal_mirrors(
        &self,
        params: TopologyParams,
    ) -> impl ::core::future::Future<Output = Result<MirrorList, RpcError>> + Send;
    /// Mark a mirrored pane Hot or Warm.
    fn terminal_set_tier(
        &self,
        params: SetTier,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Follow a pane's canonical mirror: checkpoint or replay, then ordered records.
    fn terminal_subscribe(
        &self,
        params: TerminalSubscribe,
    ) -> impl ::core::future::Future<Output = Result<Subscription, RpcError>> + Send;
    fn terminal_unsubscribe(
        &self,
        params: Unsubscribe,
    ) -> impl ::core::future::Future<Output = Result<Empty, RpcError>> + Send;
    /// Keys, text, paste, focus, or mouse for a pane, encoded against its canonical state.
    fn terminal_input(
        &self,
        params: TerminalInput,
    ) -> impl ::core::future::Future<Output = Result<InputResult, RpcError>> + Send;
}

/// Route a typed request to its method.
pub async fn dispatch<S: Service>(service: &S, request: Request) -> Result<Response, RpcError> {
    match request {
        Request::DaemonVersion(p) => service.daemon_version(p).await.map(Response::DaemonVersion),
        Request::DaemonStatus(p) => service.daemon_status(p).await.map(Response::DaemonStatus),
        Request::DaemonShutdown(p) => service
            .daemon_shutdown(p)
            .await
            .map(Response::DaemonShutdown),
        Request::TmuxTopology(p) => service.tmux_topology(p).await.map(Response::TmuxTopology),
        Request::ActionsSubmit(p) => service.actions_submit(p).await.map(Response::ActionsSubmit),
        Request::ActionsGet(p) => service.actions_get(p).await.map(Response::ActionsGet),
        Request::ActionsList(p) => service.actions_list(p).await.map(Response::ActionsList),
        Request::TerminalRead(p) => service.terminal_read(p).await.map(Response::TerminalRead),
        Request::TerminalMirrors(p) => service
            .terminal_mirrors(p)
            .await
            .map(Response::TerminalMirrors),
        Request::TerminalSetTier(p) => service
            .terminal_set_tier(p)
            .await
            .map(Response::TerminalSetTier),
        Request::TerminalSubscribe(p) => service
            .terminal_subscribe(p)
            .await
            .map(Response::TerminalSubscribe),
        Request::TerminalUnsubscribe(p) => service
            .terminal_unsubscribe(p)
            .await
            .map(Response::TerminalUnsubscribe),
        Request::TerminalInput(p) => service.terminal_input(p).await.map(Response::TerminalInput),
    }
}
